package com.slss.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="repair_logistics")
public class RepairLogistics { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="repair_order_id",nullable=false) RepairOrder order; @Column(nullable=false) String direction; String carrier; @Column(name="tracking_number") String trackingNumber; @Column(columnDefinition="TEXT") String notes; @Column(name="shipped_at") Instant shippedAt; @Column(name="received_at") Instant receivedAt; public Long getId(){return id;} public String getDirection(){return direction;} public String getCarrier(){return carrier;} public String getTrackingNumber(){return trackingNumber;} public String getNotes(){return notes;} public void setOrder(RepairOrder v){order=v;} public void setDirection(String v){direction=v;} public void setCarrier(String v){carrier=v;} public void setTrackingNumber(String v){trackingNumber=v;} public void setNotes(String v){notes=v;} }
